// @pit: {"label": "Check outdated packages, release guide, workflow pins, and SIGILL pin context"}
async ({ npm: { outdated }, workspace: { read, search }, git: { show }, shell: { exec } }) => {
  const [od, rel, pins, c420, chg, nodeV] = await Promise.all([
    outdated({}),
    read("docs/releasing.md", { format: "raw" }),
    search("uses: |node-version|npm@|npm install -g", { path: ".github", regex: true, limit: 80 }),
    show(["cc4357b", "--stat", "--format=%B"]),
    read("CHANGELOG.md", { format: "raw", limit: 40 }),
    exec("node --version; npm --version; npm view oxfmt versions --json | tail -5; npm view oxlint versions --json | tail -5"),
  ]);
  return { od: od.stdout, rel: rel.content, pins: (pins as any).matches?.map((m: any) => `${m.file}:${m.line}: ${m.text}`) ?? pins, c420: c420.stdout, chg: chg.content, nodeV: nodeV.stdout };
}
